#[test]
fn base_scaling_is_exact() {
    let r = pancakes();
    let small = r.scale_to(2).unwrap();
    assert_eq!(small.to_text(), "3/4 cup Flour\n5/8 cup Milk\n1 Egg\n1/4 tsp Salt\n");
    let back = small.scale_to(4).unwrap();
    assert_eq!(back, r);
    let same = r.scale_to(4).unwrap();
    assert_eq!(same, r);
